  crs_rev_service FLOAT64 OPTIONS(description="Total revenue for services booked through the online booking engine as reported by the Central Reservation System"),
  channel_group STRING OPTIONS(description="Filters data for metrics such as consumed revenue, room nights, and other essential statistics organized by Channel. A Channel group represents the primary classification of booking sources, categorized by business type, including CRS, PMS, or Group Sales."),
  crs_channel STRING OPTIONS(description="Filters data for metrics like consumed revenue, room nights, and other key statistics based on the Channel from the Central Reservations System. A Channel represents a grouping of sources, providing a broader perspective, such as the GDS System, Online Travel Agents, or direct bookings at the hotel."),
  ta_agency_name STRING OPTIONS(description="Filters the values for consumed revenue, room nights, and other essential metrics based on the Travel Agency Profile."),
  pms_channel STRING OPTIONS(description="Filters data for metrics like consumed revenue, room nights, and other key statistics based on the Channel from the Property Management System. A Channel represents a grouping of sources, providing a broader perspective, such as the GDS System, Online Travel Agents, or direct bookings at the hotel."),
  channel_code STRING OPTIONS(description="Filters data for metrics like consumed revenue, room nights, and other key statistics based on the Channel. A Channel represents a grouping of sources, providing a broader perspective, such as the GDS System, Online Travel Agents, or direct bookings at the hotel."),
  channel STRING OPTIONS(description="Filters data for metrics like consumed revenue, room nights, and other key statistics based on the Channel. A Channel represents a grouping of sources, providing a broader perspective, such as the GDS System, Online Travel Agents, or direct bookings at the hotel."),
  channel_sort INT64 OPTIONS(description="Used to control the sorting of dimensions within channels"),
  pms_source STRING OPTIONS(description="Filters values for consumed revenue, room nights, and other essential metrics based on the Source. Sources refer to the main channel, platform, or method used to make a hotel reservation."),
  source_code STRING OPTIONS(description="Filters values for consumed revenue, room nights, and other essential metrics based on the Source. Sources refer to the main channel, platform, or method used to make a hotel reservation."),
  source STRING OPTIONS(description="Filters values for consumed revenue, room nights, and other essential metrics based on the Source. Sources refer to the main channel, platform, or method used to make a hotel reservation."),
  source_sort INT64 OPTIONS(description="Used to control the sorting of dimensions within sources"),
  crs_subsource STRING OPTIONS(description="Filters values for consumed revenue, room nights, and other essential metrics based on the SubSource from the Central Reservation System. The subsource offers additional details about the source code, such as identifying the specific subsidiary website or ota through which a guest made their booking or the particular GDS system used"),
  pms_subsource STRING OPTIONS(description="Filters values for consumed revenue, room nights, and other essential metrics based on the SubSource from the Property Management System. The subsource offers additional details about the source code, such as identifying the specific subsidiary website or ota through which a guest made their booking or the particular GDS system used"),
  pms_subchannel STRING OPTIONS(description="Filters values for consumed revenue, room nights, and other essential metrics based on the Sub Channel from the Central Reservations System. The sub channel offers additional details about the source code, such as identifying the specific subsidiary website or ota through which a guest made their booking or the particular GDS system used"),
  subsource_code STRING OPTIONS(description="Filters values for consumed revenue, room nights, and other essential metrics based on the SubSource. The subsource offers additional details about the source code, such as identifying the specific subsidiary website or ota through which a guest made their booking or the particular GDS system used"),
  subsource STRING OPTIONS(description="Filters values for consumed revenue, room nights, and other essential metrics based on the SubSource. The subsource offers additional details about the source code, such as identifying the specific subsidiary website or ota through which a guest made their booking or the particular GDS system used"),
  cx_date TIMESTAMP OPTIONS(description="Filters the total number of reservations canceled during a given time frame. This includes all cancellations, regardless of when the bookings were initially made or the intended stay dates."),
