  cx_reason STRING OPTIONS(description="Cancellation reason code is a standardized value used to classify the reason behind a reservation cancellation. This helps in identifying trends, analyzing guest behavior, and guiding policy or operational adjustments."),
  adults INT64 OPTIONS(description="Total number of adults."),
  children INT64 OPTIONS(description="Total number of children."),
  snapshot_date TIMESTAMP OPTIONS(description="Filters the date in which the data was collected."),
